<?php
require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../helpers/auth.php';require_login();require_once __DIR__ . '/../helpers/escape.php';$pageTitle='Laporan';$rows=$pdo->query("SELECT p.id,p.sku,p.name,c.name category_name,p.stock,p.minimum_stock,p.price,COALESCE(SUM(CASE WHEN sm.type='IN' THEN sm.quantity ELSE 0 END),0) total_in,COALESCE(SUM(CASE WHEN sm.type='OUT' THEN sm.quantity ELSE 0 END),0) total_out FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN stock_movements sm ON sm.product_id=p.id GROUP BY p.id,p.sku,p.name,c.name,p.stock,p.minimum_stock,p.price ORDER BY p.name")->fetchAll();require '_header.php';
?>
<h1>Laporan Inventory</h1><div class="card"><p>Ringkasan stok, barang masuk, barang keluar, dan nilai persediaan setiap produk.</p><div class="table-wrap"><table><tr><th>SKU</th><th>Produk</th><th>Kategori</th><th>Stok sekarang</th><th>Total masuk</th><th>Total keluar</th><th>Nilai stok</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['sku'])?></td><td><?=e($r['name'])?></td><td><?=e($r['category_name'])?></td><td><?=e($r['stock'])?></td><td><?=e($r['total_in'])?></td><td><?=e($r['total_out'])?></td><td>Rp <?=number_format($r['stock']*$r['price'],0,',','.')?></td><td><?=$r['stock']<=$r['minimum_stock']?'Stok rendah':'Aman'?></td></tr><?php endforeach;?></table></div></div>
<div class="card"><h2>Ringkasan per Kategori</h2><div class="table-wrap"><table><tr><th>Kategori</th><th>Jumlah produk</th><th>Total stok</th><th>Rata-rata harga</th></tr><?php $summary=$pdo->query('SELECT c.name,COUNT(p.id) total_products,COALESCE(SUM(p.stock),0) total_stock,COALESCE(AVG(p.price),0) average_price FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id,c.name ORDER BY c.name')->fetchAll();foreach($summary as $s):?><tr><td><?=e($s['name'])?></td><td><?=e($s['total_products'])?></td><td><?=e($s['total_stock'])?></td><td>Rp <?=number_format($s['average_price'],0,',','.')?></td></tr><?php endforeach;?></table></div></div>
<?php require '_footer.php';?>
